import React, { useState } from "react";
import { Calendar } from "primereact/calendar";
import { Tooltip } from "primereact/tooltip";
import { format } from 'date-fns';
import "./css/calendar.css";

const AppointmentsCalendar = ({ appointments }) => {
  const [selectedDate, setSelectedDate] = useState(null);

  const getAppointmentStyle = (status) => {
    const styles = {
      completed: { backgroundColor: "green", color: "white" },
      pending: { backgroundColor: "yellow", color: "black" },
      confirmed: { backgroundColor: "blue", color: "white" },
      cancelled: { backgroundColor: "red", color: "white" },
    };
    return styles[status] || {};
  };

  const handleDateChange = (e) => {
    setSelectedDate(e.value);
  };

  return (
    <div>
      <Calendar
        dateFormat="mm/dd/yy"
        onChange={handleDateChange}
        inline
        monthNavigator
        yearNavigator
      />
      {selectedDate && appointments.length > 0 && (
        <div className="appointment-list">
          {appointments.map((appointment) => (
            <div
              key={appointment._id}
              style={getAppointmentStyle(appointment.status)}
              className="appointment-item"
              data-pr-tooltip={`Pet: ${appointment.pet_id.name}\nReason: ${appointment.notes}\nVet: ${appointment.vet_id.name}`}
            >
              {format(new Date(appointment.date), 'MMMM dd, yyyy')}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AppointmentsCalendar;
